// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function testFuzz_property(address actor, address log1, address log2) public {
        vm.assume(actor != address(this) && actor != address(c));
        vm.assume(log1 != address(0) && log2 != address(0));
        vm.assume(log1 != address(c) && log2 != address(c));

        // initialize once with the pre-init log binding (succeeds in both versions)
        vm.prank(actor);
        c.SetLogFile(log1);
        vm.prank(actor);
        c.Initialized();

        // after initialization, SetLogFile must ALWAYS revert, for every caller/input
        vm.prank(actor);
        bool ok;
        try c.SetLogFile(log2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}
